})

Translate("zhCN", "lore-keeper-of-norgannon", {
	title = "诺甘农的看门人",
	subtitle = "造物者记录的保管者",
	found = "奥达曼最底层的诺甘农圆盘宝藏密室",
	hint = "触摸奥达曼最底层那些巨大的白金圆盘。",
	allegiance = "造物者",
	aliases = { "诺甘农圆盘", "知识守护者", "圆盘守护者" },
	sections = {
		{
			title = "概述",
			text = [=[诺甘农的看门人是一位从诺甘农圆盘中说话的石之{link:the-night-watch}守望者{/link}。这些圆盘是四个巨大的白{link:ginro-hearthkindle}金{/link}圆环，位于{link:archaedas}阿扎达斯{/link}大厅后方的宝藏密室中，上面刻着任何学者都无法解读的符文。当有人用手触摸它们时，一个巨大的石之守望者的影像便会在旁边升起，献出它所保管的东西：造物者关于他们如何造出土灵的记录。它说话平静而精确，就像一名书记员在念账簿，而且只回答别人所问的问题。]=],
		},
		{
			title = "意义",
			text = [=[知识守护者是{link:explorers-league}探险者协会{/link}有史以来最重要的发现。它的记录回答了{link:dwarves}矮人{/link}们世世代代一直在问的问题：他们从何而来？它说，他们来自土灵，即造物者的活岩仆从，而{link:troggs}石腭怪{/link}也来自同一个源头。]=],
		},
		{
			title = "事迹",
			text = [=[• 它保管着造物者关于土灵、{link:troggs}石腭怪{/link}和{link:dwarves}矮人{/link}的记录。
• 它会给听完全部记录的人一份圆盘的小型复制品带走。]=],
		},
		{
			title = "守护者所言",
			text = [=[守护者只把泰坦称为造物者。当被问及他们是谁时，它说他们就是造物者，是播种并塑造了这个世界的人，是这个世界由之流出的源泉。它说，土灵是由世界的岩石混合而成的，而非血肉，身体强壮，头脑敏捷，并且注定要在造物者离去之后长久存在。然后它谈到了那个缺陷。在巨大的压力之下，土灵可能会瓦解，变成{link:troggs}石腭怪{/link}或{link:dwarves}矮人{/link}。当被问及什么样的压力会导致这种情况时，它停顿了一下，道了歉，说答案保存在别处。当被问及今天的矮人是否就是它记录中的矮人时，它说它无法将自己的记录与当今的时代相比较。但它确认矮人来自土灵，并称他们是一个以自己的身份当之无愧的种族。]=],
		},
	},
	chapters = {
		{
			title = "诺甘农圆盘",
			hint = "听圆盘守护者讲完它要讲述的一切。",
			text = [=[那些穿过{link:archaedas}阿扎达斯{/link}大厅的人发现宝藏密室已经打开。一阵刺痛传遍了触摸圆盘的那只手，{link:the-night-watch}守望者{/link}出现了。它要求在交出任何复制品之前，先完整地聆听它的记录。讲述结束后，圆盘嗡嗡作响。再次触摸时，它们发出一阵摩擦声，一份圆盘的微型复制品便出现在了旅人的背包里。]=],
		},
		{
			title = "送往协会",
			hint = "把微型圆盘送到探险者协会。",
			text = [=[{link:high-explorer-magellas}大探险家麦格拉斯{/link}接过微型圆盘，问它们是在哪里找到的，然后又问了一遍。当他明白过来时，他称之为本世纪最伟大的发现。他说，如果这些知识是真的，那么造物者就是{link:dwarves}矮人{/link}那受到魔法加持的诞生的关键。他命令协会尽全力研究这些圆盘。]=],
		},
		{
			title = "送往贤者",
			hint = "把微型圆盘送到雷霆崖的贤者那里。",
			text = [=[{link:sage-truthseeker}贤者求真者{/link}在圆盘中感受到了大地长久以来紧紧守护的秘密。他着手研究它们的运作方式。他确信还有多得多的东西有待发现，后来，圆盘把方向指向了南方的{link:valley-of-the-watchers}奥丹姆{/link}。]=],
		},
	},
	mentions = {
		{ text = "白{link:ginro-hearthkindle}金{/link}圆盘" },
		{ text = "白{link:ginro-hearthkindle}金{/link}圆盘" },
	},
	bonds = {
		{ id = "archaedas", name = "阿扎达斯", note = "守卫着它的密室" },
		{ id = "high-explorer-magellas", name = "大探险家麦格拉斯", note = "在铁炉堡研究它的复制品" },
		{ id = "sage-truthseeker", name = "贤者求真者", note = "在雷霆崖研究它的复制品" },
	},
})

Translate("zhCN", "the-lost-dwarves", {
	title = "失踪的矮人",
	subtitle = "巴尔洛戈、艾瑞克和奥拉夫",
	found = "奥达曼深处一座被石腭怪切断的营地",
	hint = "寻找在奥达曼被困于石腭怪防线后面的矮人。",
	allegiance = "探险者协会 · 铁炉堡王国",
	aliases = { "巴尔洛戈", "巴尔洛戈的队伍" },
	sections = {
		{
			title = "概述",
			text = [=[失踪的矮人是一支由巴尔洛戈率领的{link:ironforge}铁炉堡{/link}{link:dwarves}矮人{/link}小队，巴尔洛戈是{link:prospector-stormpike}勘察员塔伯斯·雷矛{/link}的朋友。与他同行的有被称为“迅捷者”的艾瑞克，以及大个子奥拉夫。就在{link:troggs}石腭怪{/link}涌出之前，他们深入了{link:uldaman}奥达曼{/link}的挖掘场，当身后的隧道挤满敌人时，他们被困住了。从那以后，他们一直在宝库里的一座营地中坚守。他们靠着与石腭怪战斗和拿任何事情打赌来保持斗志。奥拉夫打赌说，在他们见到一张不属于石腭怪的活人面孔之前，他的胡子就会长到膝盖。]=],
		},
		{
			title = "意义",
			text = [=[巴尔洛戈的队伍据守着{link:uldaman}奥达曼{/link}深处唯一一座友方营地。他们也守卫着它：在他们看来，任何靠近的{link:horde}部落{/link}成员都是觊觎宝库和协会秘密的窃贼，他们会奋力把这些人挡在外面。]=],
		},
	},
	chapters = {
		{
			title = "终于找到",
			hint = "回应雷矛为他失踪的朋友发出的恳求。",
			text = [=[{link:stormpike-guard}雷矛{/link}担心他的朋友已经死了。他并没有死。当援兵抵达营地时，巴尔洛戈的第一句话是，他差点就输掉了和奥拉夫的赌局，奥拉夫的胡子还差几英寸才能长够。他答应把赢来的钱分给大家。]=],
		},
		{
			title = "密室的秘密",
			hint = "阅读巴尔洛戈在日记中写下的东西。",
			text = [=[巴尔洛戈很好地利用了被困的时间。他找到了打开卡兹{link:mull-thunderhorn}穆尔{/link}密室的方法，并把每一个步骤都写进了日记：他箱子里的徽章，{link:troggs}石腭怪{/link}{link:revelosh}鲁维罗什{/link}身上的杖，用这两者做成的法杖，以及必须放置法杖的地图室。他的队伍无法离开营地。于是由其他人代替他们前往。]=],
		},
	},
	bonds = {
		{ id = "prospector-stormpike", name = "勘察员塔伯斯·雷矛", note = "巴尔洛戈的朋友" },
		{ id = "ironaya", name = "艾隆纳亚", note = "守护着巴尔洛戈找到的密室" },
	},
})

Translate("zhCN", "revelosh", {
