Translate("zhCN", "remains-of-a-paladin", {
	title = "圣骑士的遗体",
	subtitle = "一位死于奥达曼的圣骑士",
	found = "奥达曼入口附近的大神殿大厅",
	hint = "在奥达曼的大厅中寻找一位人类骑士的遗骸。",
	allegiance = "不详",
	aliases = { "奥达曼的阵亡圣骑士" },
	sections = {
		{
			title = "概述",
			text = [=[在{link:uldaman}奥达曼{/link}大神殿大厅的一条走廊里，躺着一位{link:humans}人类{/link}圣骑士的遗体。他出于自己选定的使命来到{link:badlands}废土{/link}，要净化他相信笼罩着挖掘场的一股邪恶污染。他戴着一条精美的魔法项链，那是{link:ironforge}铁炉堡{/link}的{link:gnomes}侏儒{/link}珠宝匠塔瓦斯德·基瑟尔为他打造的。他死在了宝库中，项链被扯断，宝石散落各处。他那本以人类语言写成的染血日记就躺在他身旁。]=],
		},
		{
			title = "意义",
			text = [=[这位圣骑士的死投下了长长的阴影。塔瓦斯德的一个对手散布谣言，说那条项链诅咒了它的佩戴者，这位珠宝匠的生意因此一落千丈。在{link:horde}部落{/link}中，杜弗斯父子公司的打捞者们也听说了这条项链，并想要得到它。]=],
		},
		{ title = "未载之事", text = "没有任何记录提到这位圣骑士的名字、他所属的骑士团或他的家乡。那股邪恶污染是什么，他是否找到了它，都无从知晓。" },
	},
	chapters = {
		{
			title = "圣骑士的日记",
			hint = "在奥达曼的大厅中寻找那位死去的圣骑士。",
			text = [=[这本日记是圣骑士最后的作品。他查明了每一颗宝石的去向。暗炉{link:dwarves}矮人{/link}在与{link:troggs}石腭怪{/link}争夺宝库时，把红宝石藏在了他们的路障中。石腭怪把黄玉放进了{link:ironforge}铁炉堡{/link}矮人营地附近的一只石瓮里。石腭怪的首领拿走了蓝宝石。在{link:horde}部落{/link}一方，这本日记无人能读，直到{link:kargath}卡加斯{/link}的{link:trolls}巨魔{/link}{link:jarkal-mossmeld}加卡尔{/link}将它翻译出来，以换取亲自研究这条项链的机会。]=],
		},
	},
	mentions = {
		{ text = "破碎的项链" },
		{ text = "知识的代价" },
		{ text = "找回项链" },
		{ text = "修复项链" },
	},
	bonds = {
