})

Translate("zhCN", "annora", {
	title = "安诺拉",
	subtitle = "附魔大师",
	found = "奥达曼大厅旁一个满是蝎子的洞穴",
	hint = "清理奥达曼的蝎子洞穴，看看是谁一直藏在那里。",
	allegiance = "无",
	sections = {
		{
			title = "概述",
			text = [=[安诺拉是一名{link:humans}人类{/link}附魔师，是这门技艺的大师，她藏身在{link:uldaman}奥达曼{/link}一个被蝎子占据的洞穴里。只有当这些生物被清除后，她才会出来，并真诚地感谢她的救援者：她已经开始担心自己将不得不永远躲在那里。她会把自己的技艺传授给那些赢得了它的人。]=],
		},
		{
			title = "意义",
			text = [=[安诺拉是{link:uldaman}奥达曼{/link}深处少有的友善面孔之一。一位附魔大师竟然被发现藏在宝库的蝎子群中，这是宝库中较为离奇的故事之一。]=],
